RUN_DIR="$(cat /tmp/sbb_rundir.txt)"
node -e '
const fs=require("fs");
const o=JSON.parse(fs.readFileSync(process.argv[1],"utf8"));
console.log(JSON.stringify({
  candidates:(o.candidates||[]).map(c=>({id:(c.identity&&c.identity.name)||c.id,rank:c.rank,observations:c.observationCount,mentions:(c.capabilityMentions||[]).map(m=>m.capability)})),
  coverage:o.coverage,
  evidenceLevel:o.evidence&&o.evidence.level,
  missing:o.evidence&&o.evidence.missingCapabilities,
  followUp:o.evidence&&o.evidence.needsFollowUp
},null,2));
' "$RUN_DIR/kernel-output.json" 2>&1 | head -90

